INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000335,'quizzes','{"id":760200000000335,"title":"C1 · Литературный · Чтение и жанры · Quiz 35","description":"C1: чтение и жанры. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"📝","xp":40,"category":"Чтение и жанры","track":"Литературный","topic":"Чтение и жанры","duration":"9 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «extended metaphor».","options":["критическая интерпретация","подтекстовый смысл","смена фокуса повествования","развёрнутая метафора"],"correctAnswer":"развёрнутая метафора","explanation":"«extended metaphor» — «развёрнутая метафора»."},{"id":2,"question":"Какое выражение на британском английском соответствует «ироническое преуменьшение»?","options":["implicit characterisation","shift in narrative focus","narrative ambiguity","ironic understatement"],"correctAnswer":"ironic understatement","explanation":"«ironic understatement» — «ироническое преуменьшение»."},{"id":3,"question":"Выбери точное русское значение выражения «stylistic contrast».","options":["авторский голос","смена фокуса повествования","подтекстовый смысл","стилистический контраст"],"correctAnswer":"стилистический контраст","explanation":"«stylistic contrast» — «стилистический контраст»."},{"id":4,"question":"Выбери точное русское значение выражения «implicit characterisation».","options":["косвенная характеристика персонажа","повествовательная неоднозначность","развёрнутая метафора","смена фокуса повествования"],"correctAnswer":"косвенная характеристика персонажа","explanation":"«implicit characterisation» — «косвенная характеристика персонажа»."},{"id":5,"question":"Какое выражение на британском английском соответствует «авторский голос»?","options":["critical interpretation","authorial voice","ironic understatement","intertextual reference"],"correctAnswer":"authorial voice","explanation":"«authorial voice» — «авторский голос»."},{"id":6,"question":"Выбери точное русское значение выражения «intertextual reference».","options":["смена фокуса повествования","межтекстовая отсылка","ироническое преуменьшение","литературная аллюзия"],"correctAnswer":"межтекстовая отсылка","explanation":"«intertextual reference» — «межтекстовая отсылка»."},{"id":7,"question":"Выбери точное русское значение выражения «literary allusion».","options":["стилистический контраст","смена фокуса повествования","повествовательная неоднозначность","литературная аллюзия"],"correctAnswer":"литературная аллюзия","explanation":"«literary allusion» — «литературная аллюзия»."},{"id":8,"question":"Какое выражение на британском английском соответствует «смена фокуса повествования»?","options":["stylistic contrast","shift in narrative focus","thematic coherence","subtextual meaning"],"correctAnswer":"shift in narrative focus","explanation":"«shift in narrative focus» — «смена фокуса повествования»."}],"durationMinutes":9}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
